mapper.select:
select *
from (
    select t.*, ROWNUM as rn
    from (
        select DEVICE_ID,
               STATION_CODE,
               STATUS,
               RESP_RET_CODE,
               RESP_RET_MSG,
               RESP_KEY_VERSION_COUNT,
               PROCESS_DURATION_MS,
               TO_CHAR(REQ_SYN_KEY_DATE, 'YYYY-MM-DD HH24:MI:SS') as REQ_SYN_KEY_DATE,
               TO_CHAR(REG_DATE, 'YYYY-MM-DD HH24:MI:SS') as REG_DATE,
               AGM_KEY_CURVER_LIST
        from COM_DEVICE_SYN_KEY


                and DEVICE_ID like '%' || #{deviceId} || '%'


                and STATION_CODE like '%' || #{stationCode} || '%'


                and STATUS = #{status}


        order by REQ_SYN_KEY_DATE desc nulls last, DEVICE_ID
    ) t
    where ROWNUM <= #{offset} + #{limit}
)
where rn > #{offset}
